              "prompt": "Which structure–function pair is most accurate?",
              "help_anchor": "#m03-s01-help-core",
              "answer_type": "single-choice",
              "options": [
                {
                  "option_id": "a",
                  "text": "Stems—support structures and transport materials",
                  "feedback": "Correct. Stems connect roots, leaves and reproductive parts physically and through transport tissues."
                },
                {
                  "option_id": "b",
                  "text": "Roots—capture light energy",
                  "feedback": "Leaves are usually the main light-capturing structures; roots generally anchor and absorb water and dissolved minerals."
                },
                {
                  "option_id": "c",
                  "text": "Flowers—absorb most water from the root zone",
                  "feedback": "Water uptake occurs mainly through roots; flowers are associated with reproduction."
                },
                {
                  "option_id": "d",
                  "text": "Leaves—anchor the plant in the growing medium",
                  "feedback": "Anchorage is mainly a root function."
                }
              ]
