            {
              "question_id": "m05-s02-q02",
              "prompt": "Which is a possible benefit and burden of manual top watering?",
              "help_anchor": "#m05-s02-help-core",
              "answer_type": "single-choice",
              "options": [
                {
                  "option_id": "a",
                  "text": "Simple and visible, but dependent on regular human decisions",
                  "feedback": "Correct. This is a balanced functional comparison."
                },
                {
                  "option_id": "b",
                  "text": "Requires no care and can never overdeliver",
                  "feedback": "Manual systems still depend on judgement and consistency."
                },
                {
                  "option_id": "c",
                  "text": "Cannot be observed",
                  "feedback": "Its visible action can be a strength."
                },
                {
                  "option_id": "d",
                  "text": "Always uses powered sensors",
                  "feedback": "Manual delivery does not require powered sensing."
                }
              ]
            },
            {
              "question_id": "m05-s02-q03",
              "prompt": "What is a key idea transferable from WaterWise to a school design discussion?",
              "help_anchor": "#m05-s02-help-core",
              "answer_type": "single-choice",
              "options": [
                {
                  "option_id": "a",
                  "text": "Sensors guarantee sustainable outcomes",
                  "feedback": "Sensors provide data; people still interpret and act."
                },
                {
                  "option_id": "b",
                  "text": "Every school must install the same commercial-scale system",
                  "feedback": "Scale, resources and purpose differ."
                },
                {
                  "option_id": "c",
                  "text": "Better observations and data can support better-timed irrigation decisions",
                  "feedback": "Correct. This principle can inform thinking without copying the whole technology."
                },
                {
                  "option_id": "d",
                  "text": "Plant observations are no longer useful",
                  "feedback": "Plant and system observations remain valuable evidence."
                }
              ]
            },
            {
              "question_id": "m05-s02-q04",
              "prompt": "Which is a possible burden of a passive wick system?",
              "help_anchor": "#m05-s02-help-core",
              "answer_type": "single-choice",
              "options": [
                {
                  "option_id": "a",
                  "text": "A hidden loss of contact or blockage may reduce transfer",
                  "feedback": "Correct. Passive operation still requires inspection and evidence."
                },
                {
                  "option_id": "b",
                  "text": "It always requires a powered pump",
                  "feedback": "A passive wick is designed to transfer without continuous pumping."
                },
                {
                  "option_id": "c",
                  "text": "It guarantees excessive flow",
                  "feedback": "Transfer varies; it is not guaranteed to be excessive or sufficient."
                },
                {
                  "option_id": "d",
                  "text": "It provides no water pathway",
                  "feedback": "The wick itself is intended as the transfer pathway."
                }
              ]
            },
            {
              "question_id": "m05-s02-q05",
              "prompt": "Which feature is most important in an annotated water concept?",
              "help_anchor": "#m05-s02-help-core",
              "answer_type": "single-choice",
              "options": [
                {
                  "option_id": "a",
                  "text": "Unconfirmed exact materials and dimensions",
                  "feedback": "Those local details should not be invented."
                },
                {
                  "option_id": "b",
                  "text": "A decorative border with no system information",
                  "feedback": "Decoration does not communicate water function."
                },
                {
                  "option_id": "c",
                  "text": "A guaranteed harvest statement",
                  "feedback": "A concept cannot guarantee biological performance."
                },
                {
                  "option_id": "d",
                  "text": "A visible path from source to root zone plus checking and drainage points",
                  "feedback": "Correct. It explains function and how feedback will be collected."
                }
              ]
            },
            {
              "question_id": "m05-s02-q06",
              "prompt": "Why can “automatic” be a misleading quality claim?",
              "help_anchor": "#m05-s02-help-core",
              "answer_type": "single-choice",
              "options": [
                {
                  "option_id": "a",
                  "text": "Automated systems still need suitable settings, maintenance, evidence and human oversight",
                  "feedback": "Correct. Automation changes the work; it does not remove responsibility."
                },
                {
                  "option_id": "b",
                  "text": "Automation is always cheaper",
                  "feedback": "Cost depends on the system and context."
                },
                {
                  "option_id": "c",
                  "text": "Automatic systems cannot use data",
                  "feedback": "Many automated systems rely on data."
                },
                {
                  "option_id": "d",
                  "text": "Automation means the system has no components",
                  "feedback": "Automated systems depend on components and controls."
                }
              ]
            },
            {
              "question_id": "m05-s02-q07",
              "prompt": "A care scenario has irregular human access. Which criterion becomes especially important?",
              "help_anchor": "#m05-s02-help-core",
              "answer_type": "single-choice",
              "options": [
                {
                  "option_id": "a",
                  "text": "How the system stores or delivers water between checks and reveals problems",
                  "feedback": "Correct. The design must respond to the actual care opportunity."
                },
                {
                  "option_id": "b",
                  "text": "How many decorative colours it contains",
                  "feedback": "Appearance does not address care continuity."
                },
                {
                  "option_id": "c",
                  "text": "Whether it copies a commercial farm exactly",
                  "feedback": "A school context needs an appropriately scaled solution."
                },
                {
                  "option_id": "d",
                  "text": "Whether maintenance is hidden from the plan",
                  "feedback": "Maintenance should be made explicit, especially with irregular access."
                }
              ]
            },
            {
              "question_id": "m05-s02-q08",
              "prompt": "Which option score should be challenged?",
              "help_anchor": "#m05-s02-help-core",
              "answer_type": "single-choice",
              "options": [
                {
                  "option_id": "a",
                  "text": "Low energy because the tested concept operates passively",
                  "feedback": "This is defensible within the tested concept, while other impacts still need review."
                },
                {
                  "option_id": "b",
                  "text": "High reliability because repeated tests showed consistent transfer",
                  "feedback": "This score is supported by repeated evidence, although the test context should still be stated."
                },
                {
                  "option_id": "c",
                  "text": "Perfect maintenance because the system looks simple",
                  "feedback": "Correct. Appearance alone does not prove maintainability or reveal failure points."
                },
                {
                  "option_id": "d",
                  "text": "Moderate cost based on the confirmed approved parts list",
                  "feedback": "This uses relevant local evidence rather than an unsupported visual estimate."
                }
              ]
            },
            {
              "question_id": "m05-s02-q09",
              "prompt": "What is the best reason to include an overflow or drainage path in a concept?",
              "help_anchor": "#m05-s02-help-core",
              "answer_type": "single-choice",
              "options": [
                {
                  "option_id": "a",
                  "text": "It replaces root-zone design",
                  "feedback": "Drainage is one part of the whole water system."
                },
                {
                  "option_id": "b",
                  "text": "It proves overflow will never occur",
                  "feedback": "Including a path acknowledges that excess can occur."
                },
                {
                  "option_id": "c",
                  "text": "It shows how unintended excess can leave or be observed rather than remain hidden",
                  "feedback": "Correct. The path supports both function and evidence."
                },
                {
                  "option_id": "d",
                  "text": "It guarantees zero water loss",
                  "feedback": "A drainage path manages or reveals water; it does not guarantee zero loss."
                }
              ]
            },
            {
              "question_id": "m05-s02-q10",
              "prompt": "Which final selection statement is strongest?",
              "help_anchor": "#m05-s02-help-core",
              "answer_type": "single-choice",
              "options": [
                {
                  "option_id": "a",
                  "text": "Choose the wick concept as the prototype because it matches the no-power constraint and can be inspected, while transfer still needs testing",
                  "feedback": "Correct. It links benefits, constraint, evidence and uncertainty."
                },
                {
                  "option_id": "b",
                  "text": "Choose the sensor option because it is high-tech",
                  "feedback": "This is a label, not a context-based justification."
                },
                {
                  "option_id": "c",
                  "text": "Choose manual delivery because it can never fail",
                  "feedback": "Manual decisions can be missed or inconsistent."
                },
                {
                  "option_id": "d",
                  "text": "Choose drip because all crops need identical delivery",
                  "feedback": "Crop and system needs vary; no universal claim is justified."
                }
              ]
            }
